fields.InputDefinition:
{
  "goal": "In Data Explorer > Queries, use the LEFT sidebar 'Search queries...' box (NOT the global Ctrl+K box) to find a query that requires input parameters: type 'Recent Entity Changes' (or 'Tag Distribution For Entity') and select it. Verify its Query Parameters panel appears with one or more fields marked with a red asterisk (*), indicating input is required before results are returned (the grid shows no results until a parameter is supplied). If neither named query is present, pick any query whose selection reveals a Query Parameters panel with asterisked required field(s). Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
